package com.example.mymoney.data.local.dao

import androidx.room.Dao
import androidx.room.Insert
import androidx.room.OnConflictStrategy
import androidx.room.Query
import androidx.room.Update
import com.example.mymoney.data.local.entity.SyncStatus
import com.example.mymoney.data.local.entity.WalletEntity
import kotlinx.coroutines.flow.Flow

@Dao
interface WalletDao {

    @Query("SELECT * FROM wallets WHERE user_id = :userId AND is_deleted = 0 ORDER BY is_default DESC, name ASC")
    fun observeWallets(userId: String): Flow<List<WalletEntity>>

    @Query("SELECT * FROM wallets WHERE id = :id AND is_deleted = 0")
    suspend fun getWalletById(id: Long): WalletEntity?

    @Query("SELECT * FROM wallets WHERE user_id = :userId AND is_default = 1 AND is_deleted = 0 LIMIT 1")
    suspend fun getDefaultWallet(userId: String): WalletEntity?

    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun insert(wallet: WalletEntity): Long

    @Update
    suspend fun update(wallet: WalletEntity)

    /** Soft-delete: đánh dấu is_deleted = 1, sync_status = PENDING_DELETE */
    @Query("UPDATE wallets SET is_deleted = 1, sync_status = ${SyncStatus.PENDING_DELETE}, updated_at = :now WHERE id = :id")
    suspend fun softDelete(id: Long, now: Long = System.currentTimeMillis())

    /** Trả về tất cả wallets chưa được sync lên Supabase */
    @Query("SELECT * FROM wallets WHERE user_id = :userId AND sync_status != ${SyncStatus.SYNCED}")
    suspend fun getPendingSync(userId: String): List<WalletEntity>

    /** Đánh dấu đã sync xong sau khi upsert Supabase thành công */
    @Query("UPDATE wallets SET sync_status = ${SyncStatus.SYNCED}, supabase_id = :supabaseId WHERE id = :localId")
    suspend fun markSynced(localId: Long, supabaseId: String)
}

package com.example.mymoney.data.local.dao

import androidx.room.Dao
import androidx.room.Insert
import androidx.room.OnConflictStrategy
import androidx.room.Query
import androidx.room.Update
import com.example.mymoney.data.local.entity.SyncStatus
import com.example.mymoney.data.local.entity.WalletEntity
import kotlinx.coroutines.flow.Flow

@Dao
interface WalletDao {

    @Query("SELECT * FROM wallets WHERE user_id = :userId AND is_deleted = 0 ORDER BY is_default DESC, name ASC")
    fun observeWallets(userId: String): Flow<List<WalletEntity>>

    @Query("SELECT * FROM wallets WHERE id = :id AND is_deleted = 0")
    suspend fun getWalletById(id: Long): WalletEntity?

    @Query("SELECT * FROM wallets WHERE user_id = :userId AND is_default = 1 AND is_deleted = 0 LIMIT 1")
    suspend fun getDefaultWallet(userId: String): WalletEntity?

    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun insert(wallet: WalletEntity): Long

    @Update
    suspend fun update(wallet: WalletEntity)

    /** Soft-delete: đánh dấu is_deleted = 1, sync_status = PENDING_DELETE */
    @Query("UPDATE wallets SET is_deleted = 1, sync_status = ${SyncStatus.PENDING_DELETE}, updated_at = :now WHERE id = :id")
    suspend fun softDelete(id: Long, now: Long = System.currentTimeMillis())

    /** Trả về tất cả wallets của user (kể cả đã sync) */
    @Query("SELECT * FROM wallets WHERE user_id = :userId AND is_deleted = 0")
    suspend fun getWalletsByUser(userId: String): List<WalletEntity>

    /** Trả về tất cả wallets chưa được sync lên Supabase */
    @Query("SELECT * FROM wallets WHERE user_id = :userId AND sync_status != ${SyncStatus.SYNCED}")
    suspend fun getPendingSync(userId: String): List<WalletEntity>

    /** Đánh dấu đã sync xong sau khi upsert Supabase thành công */
    @Query("UPDATE wallets SET sync_status = ${SyncStatus.SYNCED}, supabase_id = :supabaseId WHERE id = :localId")
    suspend fun markSynced(localId: Long, supabaseId: String)
}

package com.example.mymoney.data.repository

import android.util.Log
import com.example.mymoney.data.local.dao.CategoryDao
import com.example.mymoney.data.remote.SupabaseClient
import io.github.jan.supabase.gotrue.auth
import io.github.jan.supabase.postgrest.postgrest
import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable

/**
 * Repository giao tiếp với Supabase cho bảng "transactions".
 * Dùng trong AddTransactionViewModel (insert đơn) và SettingViewModel (backup batch).
 */
class SupabaseTransactionRepository(
    private val categoryDao: CategoryDao? = null
) {

    private val TAG = "SupabaseTxRepo"

    @Serializable
    private data class TransactionUpsertDto(
        @SerialName("user_id")          val userId: String,
        @SerialName("wallet_id")        val walletId: String,
        @SerialName("category_id")      val categoryId: String,
        val note: String,
        val amount: Double,
        val type: String,
        @SerialName("transaction_date") val transactionDate: String,   // ISO 8601
        @SerialName("ai_generated")     val aiGenerated: Boolean = true,
        @SerialName("created_at")       val createdAt: String          // ISO 8601
    )

    @Serializable
    private data class RemoteCategoryDto(
        val id: String,
        val name: String
    )

    /**
     * Insert 1 giao dịch mới từ AI chat lên Supabase.
     *
     * @param walletSupabaseId UUID của ví trong Supabase — null nếu ví chưa được sync.
     *                         Khi null, hàm sẽ skip upload và trả về false (non-fatal).
     * @return true nếu thành công
     */
    suspend fun insertTransaction(
        userId: String,
        note: String,
        amount: Double,
        type: String,
        category: String,
        timestampMillis: Long,
        walletSupabaseId: String?
    ): Boolean {
        // Ví chưa sync lên Supabase → chưa có UUID → skip, sẽ sync sau
        if (walletSupabaseId == null) {
            Log.d(TAG, "Skip Supabase insert: wallet not synced yet (supabase_id = null)")
            return false
        }

        return try {
            // Fetch category UUID từ Supabase theo tên
            val categoryMap = fetchCategoryMap()
            val catId = categoryMap[category] ?: categoryMap["Khác"]
            if (catId == null) {
                Log.w(TAG, "Skip Supabase insert: category '$category' not found in Supabase")
                return false
            }

            val iso = millisToIso(timestampMillis)
            val dto = TransactionUpsertDto(
                userId          = userId,
                walletId        = walletSupabaseId,
                categoryId      = catId,
                note            = note,
                amount          = amount,
                type            = type,
                transactionDate = iso,
                aiGenerated     = true,
                createdAt       = iso
            )
            SupabaseClient.client.postgrest["transactions"].insert(dto)
            Log.d(TAG, "Inserted 1 transaction to Supabase: $note $amount")
            true
        } catch (e: Exception) {
            Log.e(TAG, "Insert failed: ${e.message}", e)
            false
        }
    }

    /**
     * Fetch tất cả categories từ Supabase, trả về map name → UUID.
     * Luôn fetch trực tiếp từ Supabase, không phụ thuộc Room seed data.
     */
    private suspend fun fetchCategoryMap(): Map<String, String> {
        val remoteCats = SupabaseClient.client.postgrest["categories"]
            .select()
            .decodeList<RemoteCategoryDto>()

        Log.d(TAG, "Fetched ${remoteCats.size} categories from Supabase: ${remoteCats.map { "'${it.name}'" }}")

        // Cũng update Room cache nếu có categoryDao
        if (categoryDao != null) {
            remoteCats.forEach { remote ->
                categoryDao.updateSupabaseIdByName(remote.name, remote.id)
            }
        }

        return remoteCats.associate { it.name to it.id }
    }

    /**
     * Batch upsert toàn bộ danh sách giao dịch từ Room lên Supabase (dùng cho backup).
     * Tự động resolve category name → supabaseId (UUID) trước khi insert.
     * @return Số lượng giao dịch đã upload thành công
     */
    suspend fun upsertAll(
        userId: String,
        transactions: List<TransactionItem>
    ): Int {
        if (transactions.isEmpty()) return 0

        // ── Restore session để JWT hợp lệ ──
        try {
            SupabaseClient.client.auth.retrieveUserForCurrentSession(updateSession = true)
            Log.d(TAG, "Session restored for backup")
        } catch (e: Exception) {
            Log.w(TAG, "Could not restore session: ${e.message}")
        }

        // ── Fetch category name→UUID map trực tiếp từ Supabase ──
        val categoryMap: Map<String, String> = try {
            fetchCategoryMap()
        } catch (e: Exception) {
            Log.e(TAG, "fetchCategoryMap FAILED: ${e.message}", e)
            throw Exception("Không thể tải danh mục từ Supabase: ${e.message}")
        }

        val fallbackId: String? = categoryMap["Khác"]
        Log.d(TAG, "Fallback 'Khác' = $fallbackId")

        val dtos = transactions.mapNotNull { tx ->
            val catId = categoryMap[tx.category] ?: fallbackId
            if (catId == null) {
                Log.w(TAG, "Skipping '${tx.note}': category '${tx.category}' not in Supabase and no fallback")
                return@mapNotNull null
            }
            if (categoryMap[tx.category] == null) {
                Log.w(TAG, "Tx '${tx.note}': '${tx.category}' not found, using 'Khác' fallback")
            }
            TransactionUpsertDto(
                userId          = userId,
                walletId        = tx.walletSupabaseId ?: run {
                    Log.w(TAG, "Skip '${tx.note}': wallet not synced (supabase_id = null)")
                    return@mapNotNull null
                },
                categoryId      = catId,
                note            = tx.note,
                amount          = tx.amount,
                type            = tx.type,
                transactionDate = millisToIso(tx.timestampMillis),
                aiGenerated     = tx.aiGenerated,
                createdAt       = millisToIso(tx.timestampMillis)
            )
        }

        if (dtos.isEmpty()) {
            Log.w(TAG, "No valid DTOs — available Supabase categories: ${categoryMap.keys}")
            return 0
        }

        return try {
            SupabaseClient.client.postgrest["transactions"].insert(dtos)
            Log.d(TAG, "Batch inserted ${dtos.size} transactions to Supabase")
            dtos.size
        } catch (e: Exception) {
            Log.e(TAG, "Batch insert failed, trying one-by-one: ${e.message}")
            var successCount = 0
            dtos.forEach { dto ->
                try {
                    SupabaseClient.client.postgrest["transactions"].insert(dto)
                    successCount++
                } catch (ex: Exception) {
                    Log.w(TAG, "Skip 1 transaction: ${ex.message}")
                }
            }
            Log.d(TAG, "Fallback result: $successCount/${dtos.size} inserted")
            successCount
        }
    }

    /** epoch millis → ISO 8601 string */
    private fun millisToIso(millis: Long): String =
        java.time.Instant.ofEpochMilli(millis).toString()

    /** Lightweight model truyền dữ liệu từ Room vào repository khi backup */
    data class TransactionItem(
        val note: String,
        val amount: Double,
        val type: String,
        val category: String,
        val timestampMillis: Long,
        val walletSupabaseId: String? = null,   // null = ví chưa sync
        val aiGenerated: Boolean = false
    )
}

package com.example.mymoney.data.repository

import android.util.Log
import com.example.mymoney.data.local.dao.CategoryDao
import com.example.mymoney.data.local.dao.WalletDao
import com.example.mymoney.data.remote.SupabaseClient
import io.github.jan.supabase.gotrue.auth
import io.github.jan.supabase.postgrest.postgrest
import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable

/**
 * Repository giao tiếp với Supabase cho bảng "transactions".
 * Dùng trong AddTransactionViewModel (insert đơn) và SettingViewModel (backup batch).
 */
class SupabaseTransactionRepository(
    private val categoryDao: CategoryDao? = null,
    private val walletDao: WalletDao? = null
) {

    private val TAG = "SupabaseTxRepo"

    // ── DTOs ──────────────────────────────────────────────────────────────────

    @Serializable
    private data class TransactionUpsertDto(
        @SerialName("user_id")          val userId: String,
        @SerialName("wallet_id")        val walletId: String,
        @SerialName("category_id")      val categoryId: String,
        val note: String,
        val amount: Double,
        val type: String,
        @SerialName("transaction_date") val transactionDate: String,
        @SerialName("ai_generated")     val aiGenerated: Boolean = true,
        @SerialName("created_at")       val createdAt: String
    )

    @Serializable
    private data class RemoteCategoryDto(
        val id: String,
        val name: String
    )

    @Serializable
    private data class CategoryUpsertDto(
        @SerialName("user_id")   val userId: String,
        val name: String,
        val type: String,
        val icon: String,
        val color: String,
        @SerialName("is_system") val isSystem: Boolean = false
    )

    @Serializable
    private data class RemoteWalletDto(
        val id: String,
        val name: String
    )

    @Serializable
    private data class WalletUpsertDto(
        @SerialName("user_id")    val userId: String,
        val name: String,
        val balance: Double,
        val icon: String,
        val color: String,
        @SerialName("is_default") val isDefault: Boolean = false
    )

    // ── Single-insert (AI chat) ───────────────────────────────────────────────

    /**
     * Insert 1 giao dịch mới từ AI chat lên Supabase.
     * @param walletSupabaseId UUID ví trong Supabase — null nếu ví chưa sync.
     * @return true nếu thành công
     */
    suspend fun insertTransaction(
        userId: String,
        note: String,
        amount: Double,
        type: String,
        category: String,
        timestampMillis: Long,
        walletSupabaseId: String?
    ): Boolean {
        if (walletSupabaseId == null) {
            Log.d(TAG, "Skip Supabase insert: wallet not synced yet (supabase_id = null)")
            return false
        }
        return try {
            val categoryMap = fetchCategoryMap()
            val catId = categoryMap[category] ?: categoryMap["Khác"]
            if (catId == null) {
                Log.w(TAG, "Skip Supabase insert: category '$category' not found in Supabase")
                return false
            }
            val iso = millisToIso(timestampMillis)
            val dto = TransactionUpsertDto(
                userId          = userId,
                walletId        = walletSupabaseId,
                categoryId      = catId,
                note            = note,
                amount          = amount,
                type            = type,
                transactionDate = iso,
                aiGenerated     = true,
                createdAt       = iso
            )
            SupabaseClient.client.postgrest["transactions"].insert(dto)
            Log.d(TAG, "Inserted 1 transaction to Supabase: $note $amount")
            true
        } catch (e: Exception) {
            Log.e(TAG, "Insert failed: ${e.message}", e)
            false
        }
    }

    // ── Batch backup (SettingViewModel) ───────────────────────────────────────

    /**
     * Backup toàn bộ giao dịch Room lên Supabase.
     * Auto-sync categories & wallets trước nếu chưa có trên Supabase.
     * @return số giao dịch upload thành công
     */
    suspend fun upsertAll(userId: String, transactions: List<TransactionItem>): Int {
        if (transactions.isEmpty()) return 0

        // 1. Restore JWT session
        try {
            SupabaseClient.client.auth.retrieveUserForCurrentSession(updateSession = true)
            Log.d(TAG, "Session restored for backup")
        } catch (e: Exception) {
            Log.w(TAG, "Could not restore session: ${e.message}")
        }

        // 2. Sync categories → gets name→UUID map
        val categoryMap: Map<String, String> = try {
            syncCategoriesToSupabase(userId)
            fetchCategoryMap()
        } catch (e: Exception) {
            Log.e(TAG, "Category sync/fetch FAILED: ${e.message}", e)
            throw Exception("Không thể đồng bộ danh mục lên Supabase: ${e.message}")
        }

        val fallbackId: String? = categoryMap["Khác"]
        Log.d(TAG, "Category map size: ${categoryMap.size}, fallback 'Khác' = $fallbackId")

        // 3. Sync wallets → gets localId→supabaseId map
        val walletMap: Map<Long, String> = try {
            syncWalletsToSupabase(userId)
        } catch (e: Exception) {
            Log.w(TAG, "Wallet sync failed (non-fatal): ${e.message}")
            emptyMap()
        }
        Log.d(TAG, "Wallet map: $walletMap")

        // 4. Build DTOs
        val dtos = transactions.mapNotNull { tx ->
            val catId = categoryMap[tx.category] ?: fallbackId
            if (catId == null) {
                Log.w(TAG, "Skipping '${tx.note}': category '${tx.category}' not in Supabase")
                return@mapNotNull null
            }
            // resolve wallet: prefer already-known supabaseId, else look up from map
            val walletSupabaseId = tx.walletSupabaseId ?: walletMap[tx.walletId]
            if (walletSupabaseId == null) {
                Log.w(TAG, "Skipping '${tx.note}': wallet ${tx.walletId} not synced to Supabase")
                return@mapNotNull null
            }
            TransactionUpsertDto(
                userId          = userId,
                walletId        = walletSupabaseId,
                categoryId      = catId,
                note            = tx.note,
                amount          = tx.amount,
                type            = tx.type,
                transactionDate = millisToIso(tx.timestampMillis),
                aiGenerated     = tx.aiGenerated,
                createdAt       = millisToIso(tx.timestampMillis)
            )
        }

        if (dtos.isEmpty()) {
            Log.w(TAG, "No valid DTOs after sync. Available categories: ${categoryMap.keys}")
            return 0
        }

        // 5. Batch insert; fallback to one-by-one on error
        return try {
            SupabaseClient.client.postgrest["transactions"].insert(dtos)
            Log.d(TAG, "Batch inserted ${dtos.size} transactions")
            dtos.size
        } catch (e: Exception) {
            Log.e(TAG, "Batch insert failed, trying one-by-one: ${e.message}")
            var count = 0
            dtos.forEach { dto ->
                try {
                    SupabaseClient.client.postgrest["transactions"].insert(dto)
                    count++
                } catch (ex: Exception) {
                    Log.w(TAG, "Skip 1 transaction: ${ex.message}")
                }
            }
            Log.d(TAG, "Fallback result: $count/${dtos.size} inserted")
            count
        }
    }

    // ── Sync helpers ──────────────────────────────────────────────────────────

    /**
     * Upload local categories (chưa có supabase_id) lên Supabase.
     * Non-fatal: ghi log nhưng không throw.
     */
    private suspend fun syncCategoriesToSupabase(userId: String) {
        val dao = categoryDao ?: return
        val pending = dao.getPendingSync(userId)
        if (pending.isEmpty()) {
            Log.d(TAG, "No pending categories to sync")
            return
        }
        val dtos = pending.map { cat ->
            CategoryUpsertDto(
                userId   = userId,
                name     = cat.name,
                type     = cat.type,
                icon     = cat.icon,
                color    = cat.color,
                isSystem = cat.isSystem
            )
        }
        try {
            SupabaseClient.client.postgrest["categories"].insert(dtos)
            Log.d(TAG, "Pushed ${dtos.size} categories to Supabase")
        } catch (e: Exception) {
            Log.w(TAG, "Category push failed (will retry on next backup): ${e.message}")
        }
    }

    /**
     * Fetch tất cả categories từ Supabase → map name→UUID.
     * Cũng cập nhật Room cache (supabase_id) nếu có categoryDao.
     */
    private suspend fun fetchCategoryMap(): Map<String, String> {
        val remoteCats = SupabaseClient.client.postgrest["categories"]
            .select()
            .decodeList<RemoteCategoryDto>()

        Log.d(TAG, "Fetched ${remoteCats.size} categories from Supabase: ${remoteCats.map { "'${it.name}'" }}")

        if (categoryDao != null) {
            remoteCats.forEach { remote ->
                categoryDao.updateSupabaseIdByName(remote.name, remote.id)
            }
        }

        return remoteCats.associate { it.name to it.id }
    }

    /**
     * Upload local wallets (chưa có supabase_id) lên Supabase.
     * Sau đó query lại để lấy UUID, cập nhật Room.
     * @return Map<localWalletId, supabaseId>
     */
    private suspend fun syncWalletsToSupabase(userId: String): Map<Long, String> {
        val dao = walletDao ?: return emptyMap()

        // Upload wallets chưa sync
        val pending = dao.getPendingSync(userId)
        if (pending.isNotEmpty()) {
            val dtos = pending.map { w ->
                WalletUpsertDto(
                    userId    = userId,
                    name      = w.name,
                    balance   = w.balance,
                    icon      = w.icon,
                    color     = w.color,
                    isDefault = w.isDefault
                )
            }
            try {
                SupabaseClient.client.postgrest["wallets"].insert(dtos)
                Log.d(TAG, "Pushed ${dtos.size} wallets to Supabase")
            } catch (e: Exception) {
                Log.w(TAG, "Wallet push failed: ${e.message}")
            }
        }

        // Query lại Supabase để lấy UUID (RLS tự filter theo user)
        val remoteWallets = try {
            SupabaseClient.client.postgrest["wallets"]
                .select()
                .decodeList<RemoteWalletDto>()
        } catch (e: Exception) {
            Log.w(TAG, "Could not fetch wallets from Supabase: ${e.message}")
            return emptyMap()
        }

        Log.d(TAG, "Fetched ${remoteWallets.size} wallets from Supabase")

        // Match by name, update Room, build result map
        val nameToSupabaseId = remoteWallets.associate { it.name to it.id }
        val allLocalWallets = dao.getWalletsByUser(userId)
        val resultMap = mutableMapOf<Long, String>()

        allLocalWallets.forEach { local ->
            val supabaseId = local.supabaseId ?: nameToSupabaseId[local.name]
            if (supabaseId != null) {
                resultMap[local.id] = supabaseId
                if (local.supabaseId == null) {
                    // Update Room với supabase_id mới lấy được
                    dao.markSynced(local.id, supabaseId)
                }
            }
        }

        return resultMap
    }

    /** epoch millis → ISO 8601 string */
    private fun millisToIso(millis: Long): String =
        java.time.Instant.ofEpochMilli(millis).toString()

    /** Lightweight model truyền dữ liệu từ Room vào repository khi backup */
    data class TransactionItem(
        val note: String,
        val amount: Double,
        val type: String,
        val category: String,
        val timestampMillis: Long,
        val walletId: Long = 0L,            // local Room ID — dùng để lookup supabaseId
        val walletSupabaseId: String? = null, // nếu đã biết trước (AI insert)
        val aiGenerated: Boolean = false
    )
}

package com.example.mymoney.presentation.viewmodel.setting

import android.content.Context
import android.util.Log
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.mymoney.data.local.datastore.SettingPreferences
import com.example.mymoney.data.repository.SupabaseTransactionRepository
import com.example.mymoney.domain.repository.AuthRepository
import com.example.mymoney.domain.repository.TransactionRepository
import com.example.mymoney.presentation.viewmodel.setting.setting.SettingEvent
import com.example.mymoney.presentation.viewmodel.setting.setting.SettingNavEvent
import com.example.mymoney.presentation.viewmodel.setting.setting.SettingUiState
import kotlinx.coroutines.flow.MutableSharedFlow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharedFlow
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asSharedFlow
import kotlinx.coroutines.flow.combine
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch

/** Internal state cho backup — tách riêng để combine dễ hơn */
private data class BackupViewState(
    val isBackingUp: Boolean = false,
    val showDialog: Boolean = false,
    val resultMsg: String? = null
)

/**
 * ViewModel quản lý logic và trạng thái cho màn hình Cài đặt.
 */
class SettingViewModel(
    private val settingPreferences: SettingPreferences,
    private val authRepository: AuthRepository,
    private val transactionRepository: TransactionRepository,
    private val supabaseTransactionRepo: SupabaseTransactionRepository
) : ViewModel() {

    private val TAG = "SettingViewModel"

    // ── UI state: merge DataStore flows + backup state ──
    private val _backupState = MutableStateFlow(BackupViewState())

    val uiState: StateFlow<SettingUiState> =
        combine(
            settingPreferences.isThousandSeparatorEnabled,
            settingPreferences.currentUsername,
            _backupState
        ) { enabled, username, backup ->
            SettingUiState(
                isThousandSeparatorEnabled = enabled,
                username                   = username ?: "",
                isBackingUp                = backup.isBackingUp,
                showBackupConfirmDialog    = backup.showDialog,
                backupResultMessage        = backup.resultMsg
            )
        }.stateIn(
            scope        = viewModelScope,
            started      = SharingStarted.WhileSubscribed(5000),
            initialValue = SettingUiState()
        )

    // sự kiện điều hướng cho Navigation Component
    private val _navEvent = MutableSharedFlow<SettingNavEvent>()
    val navEvent: SharedFlow<SettingNavEvent> = _navEvent.asSharedFlow()


    /** Xử lý sự kiện từ UI */
    fun onEvent(event: SettingEvent) {
        when (event) {
            is SettingEvent.ToggleThousandSeparator -> {
                viewModelScope.launch {
                    settingPreferences.setThousandSeparatorEnabled(event.enabled)
                }
            }
            is SettingEvent.SignOut -> {
                viewModelScope.launch {
                    authRepository.signOut()
                    settingPreferences.clearUserId()
                    settingPreferences.clearUsername()   // xóa username cùng lúc
                    _navEvent.emit(SettingNavEvent.NavigateToSignIn)
                }
            }
            // Nhấn item "Dữ liệu và sao lưu" → hiện dialog xác nhận
            is SettingEvent.BackupToSupabaseClicked -> {
                _backupState.update { it.copy(showDialog = true) }
            }
            // Xác nhận trong dialog → bắt đầu backup
            is SettingEvent.BackupConfirmed -> {
                _backupState.update { it.copy(showDialog = false) }
                startBackup()
            }
            // Đóng dialog không làm gì
            is SettingEvent.BackupDismissed -> {
                _backupState.update { it.copy(showDialog = false) }
            }
            // Đóng thông báo kết quả
            is SettingEvent.DismissBackupResult -> {
                _backupState.update { it.copy(resultMsg = null) }
            }
        }
    }

    // ──────────────────────────────────────────────────────────────────────────
    // Backup logic: Room → Supabase
    // ──────────────────────────────────────────────────────────────────────────

    private fun startBackup() {
        viewModelScope.launch {
            // 1. Bắt đầu loading
            _backupState.update { BackupViewState(isBackingUp = true) }

            try {
                // 2. Lấy userId từ DataStore
                val userId = settingPreferences.currentUserId.first()
                if (userId.isNullOrBlank()) {
                    _backupState.update { BackupViewState(resultMsg = "⚠️ Chưa đăng nhập. Không thể sao lưu.") }
                    return@launch
                }

                // 3. Đọc tất cả giao dịch của userId từ Room (1 snapshot)
                val transactions = transactionRepository.getAllTransactions(userId).first()

                if (transactions.isEmpty()) {
                    _backupState.update { BackupViewState(resultMsg = "ℹ️ Không có giao dịch nào để sao lưu.") }
                    return@launch
                }

                // 4. Map sang DTO
                val dtos = transactions.map { tx ->
                    SupabaseTransactionRepository.TransactionItem(
                        note            = tx.note,
                        amount          = tx.amount,
                        type            = tx.type,
                        category        = tx.category,
                        timestampMillis = tx.timestamp
                    )
                }

                // 5. Upsert lên Supabase
                val count = supabaseTransactionRepo.upsertAll(userId, dtos)

                val msg = if (count == dtos.size)
                    "✅ Đã sao lưu $count giao dịch lên đám mây."
                else
                    "⚠️ Sao lưu một phần: $count/${dtos.size} giao dịch thành công."

                _backupState.update { BackupViewState(resultMsg = msg) }
                Log.d(TAG, msg)

            } catch (e: Exception) {
                Log.e(TAG, "Backup failed: ${e.message}", e)
                _backupState.update {
                    BackupViewState(resultMsg = "❌ Sao lưu thất bại: ${e.message ?: "Lỗi không xác định"}")
                }
            }
        }
    }

    companion object {
        fun factory(context: Context) = SettingViewModelFactory(context)
    }
}

package com.example.mymoney.presentation.viewmodel.setting

import android.content.Context
import android.util.Log
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.mymoney.data.local.datastore.SettingPreferences
import com.example.mymoney.data.repository.SupabaseTransactionRepository
import com.example.mymoney.domain.repository.AuthRepository
import com.example.mymoney.domain.repository.TransactionRepository
import com.example.mymoney.presentation.viewmodel.setting.setting.SettingEvent
import com.example.mymoney.presentation.viewmodel.setting.setting.SettingNavEvent
import com.example.mymoney.presentation.viewmodel.setting.setting.SettingUiState
import kotlinx.coroutines.flow.MutableSharedFlow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharedFlow
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asSharedFlow
import kotlinx.coroutines.flow.combine
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch

/** Internal state cho backup — tách riêng để combine dễ hơn */
private data class BackupViewState(
    val isBackingUp: Boolean = false,
    val showDialog: Boolean = false,
    val resultMsg: String? = null
)

/**
 * ViewModel quản lý logic và trạng thái cho màn hình Cài đặt.
 */
class SettingViewModel(
    private val settingPreferences: SettingPreferences,
    private val authRepository: AuthRepository,
    private val transactionRepository: TransactionRepository,
    private val supabaseTransactionRepo: SupabaseTransactionRepository
) : ViewModel() {

    private val TAG = "SettingViewModel"

    // ── UI state: merge DataStore flows + backup state ──
    private val _backupState = MutableStateFlow(BackupViewState())

    val uiState: StateFlow<SettingUiState> =
        combine(
            settingPreferences.isThousandSeparatorEnabled,
            settingPreferences.currentUsername,
            _backupState
        ) { enabled, username, backup ->
            SettingUiState(
                isThousandSeparatorEnabled = enabled,
                username                   = username ?: "",
                isBackingUp                = backup.isBackingUp,
                showBackupConfirmDialog    = backup.showDialog,
                backupResultMessage        = backup.resultMsg
            )
        }.stateIn(
            scope        = viewModelScope,
            started      = SharingStarted.WhileSubscribed(5000),
            initialValue = SettingUiState()
        )

    // sự kiện điều hướng cho Navigation Component
    private val _navEvent = MutableSharedFlow<SettingNavEvent>()
    val navEvent: SharedFlow<SettingNavEvent> = _navEvent.asSharedFlow()


    /** Xử lý sự kiện từ UI */
    fun onEvent(event: SettingEvent) {
        when (event) {
            is SettingEvent.ToggleThousandSeparator -> {
                viewModelScope.launch {
                    settingPreferences.setThousandSeparatorEnabled(event.enabled)
                }
            }
            is SettingEvent.SignOut -> {
                viewModelScope.launch {
                    authRepository.signOut()
                    settingPreferences.clearUserId()
                    settingPreferences.clearUsername()   // xóa username cùng lúc
                    _navEvent.emit(SettingNavEvent.NavigateToSignIn)
                }
            }
            // Nhấn item "Dữ liệu và sao lưu" → hiện dialog xác nhận
            is SettingEvent.BackupToSupabaseClicked -> {
                _backupState.update { it.copy(showDialog = true) }
            }
            // Xác nhận trong dialog → bắt đầu backup
            is SettingEvent.BackupConfirmed -> {
                _backupState.update { it.copy(showDialog = false) }
                startBackup()
            }
            // Đóng dialog không làm gì
            is SettingEvent.BackupDismissed -> {
                _backupState.update { it.copy(showDialog = false) }
            }
            // Đóng thông báo kết quả
            is SettingEvent.DismissBackupResult -> {
                _backupState.update { it.copy(resultMsg = null) }
            }
        }
    }

    // ──────────────────────────────────────────────────────────────────────────
    // Backup logic: Room → Supabase
    // ──────────────────────────────────────────────────────────────────────────

    private fun startBackup() {
        viewModelScope.launch {
            // 1. Bắt đầu loading
            _backupState.update { BackupViewState(isBackingUp = true) }

            try {
                // 2. Lấy userId từ DataStore
                val userId = settingPreferences.currentUserId.first()
                if (userId.isNullOrBlank()) {
                    _backupState.update { BackupViewState(resultMsg = "⚠️ Chưa đăng nhập. Không thể sao lưu.") }
                    return@launch
                }

                // 3. Đọc tất cả giao dịch của userId từ Room (1 snapshot)
                val transactions = transactionRepository.getAllTransactions(userId).first()

                if (transactions.isEmpty()) {
                    _backupState.update { BackupViewState(resultMsg = "ℹ️ Không có giao dịch nào để sao lưu.") }
                    return@launch
                }

                // 4. Map sang DTO
                val dtos = transactions.map { tx ->
                    SupabaseTransactionRepository.TransactionItem(
                        note            = tx.note,
                        amount          = tx.amount,
                        type            = tx.type,
                        category        = tx.category,
                        timestampMillis = tx.timestamp,
                        walletId        = tx.walletId,   // local Room ID → resolved to UUID by repo
                        aiGenerated     = tx.aiGenerated
                    )
                }

                // 5. Upsert lên Supabase
                val count = supabaseTransactionRepo.upsertAll(userId, dtos)

                val msg = if (count == dtos.size)
                    "✅ Đã sao lưu $count giao dịch lên đám mây."
                else
                    "⚠️ Sao lưu một phần: $count/${dtos.size} giao dịch thành công."

                _backupState.update { BackupViewState(resultMsg = msg) }
                Log.d(TAG, msg)

            } catch (e: Exception) {
                Log.e(TAG, "Backup failed: ${e.message}", e)
                _backupState.update {
                    BackupViewState(resultMsg = "❌ Sao lưu thất bại: ${e.message ?: "Lỗi không xác định"}")
                }
            }
        }
    }

    companion object {
        fun factory(context: Context) = SettingViewModelFactory(context)
    }
}

package com.example.mymoney.presentation.viewmodel.setting

import android.content.Context
import androidx.lifecycle.ViewModel
import androidx.lifecycle.ViewModelProvider
import com.example.mymoney.data.local.datastore.SettingPreferences
import com.example.mymoney.data.local.db.AppDatabase
import com.example.mymoney.data.repository.AuthRepositoryImpl
import com.example.mymoney.data.repository.SupabaseTransactionRepository
import com.example.mymoney.data.repository.TransactionRepositoryImpl

/**
 * Factory inject toàn bộ dependency chain:
 *   AppDatabase → DAO → RepositoryImpl → SettingViewModel
 *
 * @param context  ApplicationContext (hoặc Activity context)
 * @param userId   ID người dùng hiện tại — dùng để filter Room queries theo user
 */
class SettingViewModelFactory(
    private val context: Context
) : ViewModelProvider.Factory {

    @Suppress("UNCHECKED_CAST")
    override fun <T : ViewModel> create(modelClass: Class<T>): T {
        require(modelClass.isAssignableFrom(SettingViewModel::class.java)) {
            "Unknown ViewModel: ${modelClass.name}"
        }
        val appCtx = context.applicationContext
        val db     = AppDatabase.getInstance(appCtx)

        return SettingViewModel(
            settingPreferences      = SettingPreferences(appCtx),
            authRepository          = AuthRepositoryImpl(),
            transactionRepository   = TransactionRepositoryImpl(db.transactionDao()),
            supabaseTransactionRepo = SupabaseTransactionRepository(db.categoryDao())
        ) as T
    }
}

package com.example.mymoney.presentation.viewmodel.setting

import android.content.Context
import androidx.lifecycle.ViewModel
import androidx.lifecycle.ViewModelProvider
import com.example.mymoney.data.local.datastore.SettingPreferences
import com.example.mymoney.data.local.db.AppDatabase
import com.example.mymoney.data.repository.AuthRepositoryImpl
import com.example.mymoney.data.repository.SupabaseTransactionRepository
import com.example.mymoney.data.repository.TransactionRepositoryImpl

/**
 * Factory inject toàn bộ dependency chain:
 *   AppDatabase → DAO → RepositoryImpl → SettingViewModel
 *
 * @param context  ApplicationContext (hoặc Activity context)
 * @param userId   ID người dùng hiện tại — dùng để filter Room queries theo user
 */
class SettingViewModelFactory(
    private val context: Context
) : ViewModelProvider.Factory {

    @Suppress("UNCHECKED_CAST")
    override fun <T : ViewModel> create(modelClass: Class<T>): T {
        require(modelClass.isAssignableFrom(SettingViewModel::class.java)) {
            "Unknown ViewModel: ${modelClass.name}"
        }
        val appCtx = context.applicationContext
        val db     = AppDatabase.getInstance(appCtx)

        return SettingViewModel(
            settingPreferences      = SettingPreferences(appCtx),
            authRepository          = AuthRepositoryImpl(),
            transactionRepository   = TransactionRepositoryImpl(db.transactionDao()),
